/* @autogenerated */
import type { Content, ContentText, TDocumentDefinitions } from 'pdfmake/interfaces';
import { Block, Run } from './document.model';

const HEADING_SIZES = [20, 16, 14, 12, 11, 10];

/** Bloques a un PDF (texto real, seleccionable). */
export async function writePdf(blocks: Block[], title = ''): Promise<Blob> {
  const [pdfMake, fonts] = await Promise.all([import('pdfmake/build/pdfmake'), import('pdfmake/build/vfs_fonts')]);
  const make = ((pdfMake as any).default ?? pdfMake) as typeof import('pdfmake/build/pdfmake');
  make.addVirtualFileSystem(((fonts as any).default ?? fonts) as any);
  return make.createPdf(pdfDefinition(blocks, title)).getBlob();
}

/** Definición de pdfmake para los bloques. */
export function pdfDefinition(blocks: Block[], title = ''): TDocumentDefinitions {
  return {
    info: { title },
    pageMargins: [56, 56, 56, 56],
    defaultStyle: { fontSize: 10, lineHeight: 1.2 },
    content: content(blocks),
  };
}

function content(blocks: Block[]): Content[] {
  return blocks.map((block): Content => {
    switch (block.kind) {
      case 'heading':
        return {
          text: runs(block.runs),
          fontSize: HEADING_SIZES[block.level - 1],
          bold: true,
          margin: [0, block.level === 1 ? 0 : 10, 0, 6],
        };
      case 'paragraph':
        return { text: runs(block.runs), margin: [0, 0, 0, 6] };
      case 'list': {
        const items = block.items.map((item) => (item.length === 1 ? content(item)[0] : { stack: content(item) }));
        return block.ordered
          ? { ol: items, start: block.start, margin: [0, 0, 0, 6] }
          : { ul: items, margin: [0, 0, 0, 6] };
      }
      case 'table': {
        const cell = (cellRuns: Run[], index: number, header: boolean): Content => ({
          text: runs(cellRuns),
          bold: header || undefined,
          fillColor: header ? '#EEEEEE' : undefined,
          alignment: block.align[index] ?? 'left',
        });
        return {
          table: {
            headerRows: 1,
            widths: block.header.map(() => '*'),
            body: [
              block.header.map((header, index) => cell(header, index, true)),
              ...block.rows.map((row) => row.map((cells, index) => cell(cells, index, false))),
            ],
          },
          layout: 'lightHorizontalLines',
          margin: [0, 0, 0, 8],
        };
      }
      case 'code':
        return {
          table: { widths: ['*'], body: [[{ text: block.text, fontSize: 9, preserveLeadingSpaces: true }]] },
          layout: { fillColor: () => '#F3F3F3', hLineWidth: () => 0, vLineWidth: () => 0 },
          margin: [0, 0, 0, 8],
        };
      case 'quote':
        return { stack: content(block.blocks), margin: [16, 0, 0, 6], color: '#555555' };
      case 'rule':
        return {
          canvas: [{ type: 'line', x1: 0, y1: 0, x2: 483, y2: 0, lineWidth: 0.5, lineColor: '#BBBBBB' }],
          margin: [0, 6, 0, 6],
        };
      case 'pagebreak':
        return { text: '', pageBreak: 'after' };
    }
  });
}

function runs(items: Run[]): ContentText['text'] {
  return items.map((run) =>
    run.break
      ? '\n'
      : {
          text: run.text,
          bold: run.bold,
          italics: run.italic,
          decoration: run.strike ? 'lineThrough' : run.link ? 'underline' : undefined,
          link: run.link,
          color: run.link ? '#1a5fb4' : undefined,
          background: run.code ? '#F3F3F3' : undefined,
        },
  );
}
